package io.knowledgebrain.integration;
import java.time.*;import java.util.*;import org.junit.jupiter.api.*;import org.junit.jupiter.api.condition.EnabledIfEnvironmentVariable;import static org.junit.jupiter.api.Assertions.*;import org.flywaydb.core.Flyway;import org.postgresql.ds.PGSimpleDataSource;import org.springframework.jdbc.core.JdbcTemplate;
@EnabledIfEnvironmentVariable(named="BRAIN_TEST_INTEGRATION_DATABASE_URL",matches=".+")
class GitHubWorkMigrationTest {
 @Test void v1CommitFactsAndReceiptsRemainByteIdenticalAndWorkOutboxFailureRollsBackNewTables(){var ds=new PGSimpleDataSource();ds.setURL(System.getenv("BRAIN_TEST_INTEGRATION_DATABASE_URL"));ds.setUser("brain_integration");ds.setPassword(System.getenv("BRAIN_TEST_INTEGRATION_DATABASE_PASSWORD"));var sql=new JdbcTemplate(ds);String schema="github_work_test_"+UUID.randomUUID().toString().replace("-","");assertTrue(schema.matches("github_work_test_[a-f0-9]{32}"));sql.execute("CREATE SCHEMA "+schema);try{ds.setCurrentSchema(schema);Flyway.configure().dataSource(ds).target("1").load().migrate();var clock=Clock.systemUTC();var ids=new UuidV7(clock);var store=new GitHubStore(ds,clock);UUID space=ids.next(),actor=ids.next();String trace="a".repeat(32),key=UUID.randomUUID().toString().replace("-","");var source=new GitHubClient.Repository("1296269","octocat/Hello-World","https://github.com/octocat/Hello-World","main");var parent=store.connect(space,actor,key,"https://github.com/octocat/hello-world",source,trace).repository();var sync=store.sync(space,parent.repositoryId(),actor,UUID.randomUUID().toString().replace("-",""),1,new GitHubClient.Batch(source,List.of(new GitHubClient.Commit("a".repeat(40),"Original",null,"2020-01-01T00:00:00Z")),"a".repeat(40),false),trace);var commits=store.commits(space,parent.repositoryId(),null,20);var history=store.history(space,parent.repositoryId(),Long.MAX_VALUE,10);var before=sql.queryForList("SELECT id,encode(payload,'hex') AS wire FROM outbox_event ORDER BY id");Flyway.configure().dataSource(ds).load().migrate();assertEquals(commits,store.commits(space,parent.repositoryId(),null,20));assertEquals(history,store.history(space,parent.repositoryId(),Long.MAX_VALUE,10));assertEquals(List.of(sync.sync()),store.syncs(space,parent.repositoryId(),null,20).items());assertEquals(before,sql.queryForList("SELECT id,encode(payload,'hex') AS wire FROM outbox_event ORDER BY id"));var work=new GitHubWorkStore(ds,clock,store);var input=new GitHubWorkClient.Batch(source,"ISSUE",List.of(new GitHubWorkClient.Item("42",7,"New issue","OPEN",null,null,"2020-01-01T00:00:00Z","2020-01-02T00:00:00Z",null,source.url()+"/issues/7")),1,false);sql.execute("ALTER TABLE outbox_event ADD CONSTRAINT work_test_fail CHECK(aggregatetype<>'github-issue')");assertThrows(org.springframework.dao.DataIntegrityViolationException.class,()->work.sync(space,parent.repositoryId(),"ISSUE",actor,UUID.randomUUID().toString().replace("-",""),0,input,trace));assertEquals(0,work.state(space,parent.repositoryId(),"ISSUE").version());assertTrue(work.page(space,parent.repositoryId(),"ISSUE","ALL",null,20).items().isEmpty());assertTrue(work.syncs(space,parent.repositoryId(),"ISSUE",null,20).items().isEmpty());assertEquals(before,sql.queryForList("SELECT id,encode(payload,'hex') AS wire FROM outbox_event ORDER BY id"));sql.execute("ALTER TABLE outbox_event DROP CONSTRAINT work_test_fail");assertEquals(1,work.sync(space,parent.repositoryId(),"ISSUE",actor,UUID.randomUUID().toString().replace("-",""),0,input,trace).sync().importedCount());assertEquals(2,store.get(space,parent.repositoryId()).version());}finally{ds.setCurrentSchema("public");new JdbcTemplate(ds).execute("DROP SCHEMA "+schema+" CASCADE");}}
}
